interface TextAnimationOptions {
  threshold?: number;
  rootMargin?: string;
  staggerDelay?: number;
  revealSpeed?: number;
}

class TextAnimation extends HTMLElement {
  private observer: IntersectionObserver;
  private options: Required<TextAnimationOptions>;
  private words: HTMLElement[] = [];
  private isInView: boolean = false;
  private scrollHandler: () => void;

  constructor() {
    super();

    this.options = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
      staggerDelay: 50,
      revealSpeed: 0.8, // How fast words reveal (0-1, where 1 is fastest)
    };

    this.scrollHandler = this.handleScroll.bind(this);

    this.observer = new IntersectionObserver(
      this.handleIntersection.bind(this),
      {
        threshold: this.options.threshold,
        rootMargin: this.options.rootMargin,
      },
    );
  }

  connectedCallback(): void {
    this.init();
  }

  disconnectedCallback(): void {
    this.destroy();
  }

  private init(): void {
    this.prepareText();
    this.observer.observe(this);
  }

  private prepareText(): void {
    const contentContainer = this.querySelector(
      ".richtext__content",
    ) as HTMLElement;
    if (!contentContainer) return;

    // Get all text nodes and split into words
    this.splitTextIntoWords(contentContainer);
  }

  private splitTextIntoWords(element: HTMLElement): void {
    // Only target elements with .heading__text class
    const headings = element.querySelectorAll(".heading__text");

    headings.forEach((heading) => {
      const walker = document.createTreeWalker(
        heading,
        NodeFilter.SHOW_TEXT,
        null,
      );

      const textNodes: Text[] = [];
      let node;

      // Collect all text nodes within this heading
      while ((node = walker.nextNode())) {
        if (node.textContent?.trim()) {
          textNodes.push(node as Text);
        }
      }

      // Process each text node within the heading
      textNodes.forEach((textNode) => {
        const parent = textNode.parentNode as HTMLElement;
        if (!parent) return;

        const words = textNode.textContent?.split(/(\s+)/) || [];
        const fragment = document.createDocumentFragment();

        words.forEach((word) => {
          if (word.trim()) {
            // Create span for actual words
            const span = document.createElement("span");
            span.textContent = word;
            span.classList.add("text-animation-word");
            this.words.push(span);
            fragment.appendChild(span);
          } else if (word) {
            // Preserve whitespace
            fragment.appendChild(document.createTextNode(word));
          }
        });

        parent.replaceChild(fragment, textNode);
      });
    });
  }

  private handleIntersection(entries: IntersectionObserverEntry[]): void {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        this.isInView = true;
        window.addEventListener("scroll", this.scrollHandler, {
          passive: true,
        });
        this.handleScroll(); // Initial calculation
      } else {
        this.isInView = false;
        window.removeEventListener("scroll", this.scrollHandler);
        // Reset words when out of view
        this.resetWords();
      }
    });
  }

  private handleScroll(): void {
    if (!this.isInView || this.words.length === 0) return;

    const rect = this.getBoundingClientRect();
    const windowHeight = window.innerHeight;
    const startDelay = windowHeight * 0.45; // 45vh delay before animation starts

    // Calculate how much of the element has been scrolled through
    const elementTop = rect.top;
    const elementBottom = rect.bottom;
    const elementHeight = rect.height;

    // Check if we're at the bottom of the page
    const isAtBottom =
      window.innerHeight + window.scrollY >=
      document.documentElement.scrollHeight - 10;

    // Calculate scroll progress through the element
    let scrollProgress = 0;

    if (elementTop <= windowHeight && elementBottom >= 0) {
      // Element is in viewport
      const visibleTop = Math.max(0, windowHeight - elementTop);
      const adjustedVisibleTop = Math.max(0, visibleTop - startDelay);

      // Calculate animation completion point - finish when 80% through the element
      const animationCompletionPoint = elementHeight * 0.8;

      scrollProgress = Math.min(
        1,
        adjustedVisibleTop /
          (animationCompletionPoint * this.options.revealSpeed),
      );

      // Alternative: Complete animation when element bottom reaches viewport bottom
      // This ensures animation finishes exactly when user reaches the end of the section
      // if (elementBottom <= windowHeight) {
      //   scrollProgress = 1;
      // }

      // If we're at the bottom of the page and the element is visible, complete the animation
      if (isAtBottom && elementBottom <= windowHeight) {
        scrollProgress = 1;
      }
    }

    // Calculate how many words should be visible
    const wordsToShow = Math.floor(scrollProgress * this.words.length);

    // Reveal words progressively using CSS classes
    this.words.forEach((word, index) => {
      if (index < wordsToShow) {
        word.classList.add("text-animation-word--visible");
      } else {
        word.classList.remove("text-animation-word--visible");
      }
    });
  }

  private resetWords(): void {
    this.words.forEach((word) => {
      word.classList.remove("text-animation-word--visible");
    });
  }

  public destroy(): void {
    this.observer.disconnect();
    window.removeEventListener("scroll", this.scrollHandler);
    this.words = [];
  }

  public refresh(): void {
    this.destroy();
    this.init();
  }
}

customElements.define("uwp-text-animation", TextAnimation);
